std::optional<Config> load_config(const fs::path& path)
{
    if (!fs::exists(path))
        return std::nullopt;              // guard: the happy path stays flat
    if (fs::file_size(path) > kMaxBytes)
        return std::nullopt;

    std::ifstream in{path};
    auto parsed = parse(in);              // one nesting level only
    if (!parsed)
        return std::nullopt;
    return normalize(*parsed);
}
